// Build WhatsApp error notification
const e = $json.execution || {};
const err = e.error || {};
const msg = [
  '🚨 *Workflow Error Alert*',
  '',
  '📋 Workflow: ' + ($json.workflow?.name || 'Social Media Publisher'),
  '🆔 Execution: ' + (e.id || 'unknown'),
  '📍 Last Node: ' + (e.lastNodeExecuted || 'unknown'),
  '',
  '❌ Error:',
  (err.message || 'Unknown error').substring(0, 300),
  '',
  '⏰ Time: ' + new Date().toISOString(),
  '',
  '🔗 View: ' + (e.url || 'Check n8n dashboard')
].join('\n');

return {
  json: {
    messaging_product: 'whatsapp',
    to: '+9779845670262',
    type: 'text',
    text: { preview_url: false, body: msg }
  }
};

// ── Parse AI response ──────────────────────────────────────────────────────
const aiNode = $('🤖 AI: Generate Platform Content').first();
let ai = {};
try {
  ai = JSON.parse(aiNode.json.choices[0].message.content);
} catch (e) {
  throw new Error(
    '⚠️ Failed to parse OpenAI JSON response. ' +
    'Raw: ' + JSON.stringify(aiNode.json).substring(0, 400)
  );
}

// ── Validate required AI fields ───────────────────────────────────────────
const required = [
  'facebook_post_caption','facebook_reels_caption','facebook_story_text',
  'instagram_post_caption','instagram_reels_caption','instagram_story_text',
  'youtube_video_title','youtube_video_description','youtube_video_tags',
  'youtube_shorts_title','tiktok_video_caption','tiktok_story_text',
  'content_summary','hashtags'
];
const fallback = ai.facebook_post_caption || 'Check out this video!';
for (const field of required) {
  if (!ai[field]) ai[field] = field.endsWith('tags') || field === 'hashtags' ? ['#video'] : fallback;
}
if (!Array.isArray(ai.youtube_video_tags)) ai.youtube_video_tags = ['video'];
if (!Array.isArray(ai.hashtags)) ai.hashtags = ['#video'];

// ── Build item ─────────────────────────────────────────────────────────────
const fi = $('⚙️ SET: Extract File Info').first().json;

return {
  json: {
    ...ai,
    fileId:            fi.fileId,
    fileName:          fi.fileName,
    mimeType:          fi.mimeType || 'video/mp4',
    fileSize:          fi.fileSize || 0,
    publicUrl:         fi.publicUrl,
    shareUrl:          fi.shareUrl,
    description:       fi.description,
    uploadFolderId:    fi.uploadFolderId,
    completedFolderId: fi.completedFolderId,
    _processedAt:      new Date().toISOString(),
    _status:           {}
  },
  binary: $input.item.binary
};

// Build the approval WhatsApp message with approve/reject links
// $execution.resumeUrl is the n8n Wait node webhook resume URL
const base    = $input.item.json;
const resumeUrl = $execution.resumeUrl || 'https://YOUR_N8N_INSTANCE/webhook-waiting/PLACEHOLDER';

const approveUrl = resumeUrl + '?reply=approve';
const rejectUrl  = resumeUrl + '?reply=reject';

const contentPreview = [
  '📝 *Facebook:* ' + (base.facebook_post_caption || '').substring(0, 80),
  '🎬 *YouTube:* '  + (base.youtube_video_title   || ''),
  '🎵 *TikTok:* '   + (base.tiktok_video_caption  || '').substring(0, 80),
  '',
  '📌 *Summary:* '  + (base.content_summary || '').substring(0, 120),
].join('\n');

const tags = Array.isArray(base.hashtags) ? base.hashtags.slice(0,5).join(' ') : '';

const msgBody = [
  '🎬 *New Video Ready to Publish*',
  '━━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  '📁 *File:* ' + base.fileName,
  '🔗 *Preview:* ' + base.shareUrl,
  '📦 *Size:* ' + (Math.round((base.fileSize||0)/1024/1024*10)/10) + ' MB',
  '',
  '📢 *Content Preview:*',
  contentPreview,
  '',
  tags,
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━',
  '✅ *APPROVE & Upload:*',
  approveUrl,
  '',
  '❌ *CANCEL Upload:*',
  rejectUrl,
  '',
  '⏰ _Auto-proceeds in 2 min if no response._'
].join('\n');

return {
  json: {
    ...base,
    _approveUrl:   approveUrl,
    _rejectUrl:    rejectUrl,
    _waApprovalMsg: msgBody
  },
  binary: $input.item.binary
};

// Check if we received a webhook response or timed out
const resp = $input.item.json || {};
const isTimedOut = !resp || Object.keys(resp).length === 0 ||
                   resp._waitTimedOut === true || resp.timeout === true;

const reply   = (resp?.query?.reply || '').toLowerCase().trim();
const isStop  = reply === 'reject' || reply === 'stop' || reply === 'cancel' || reply === 'no';
const isApprove = reply === 'approve' || reply === 'ok' || reply === 'yes' || isTimedOut;

// Restore the assembled data which was stored before the Wait node
const base = $('🧩 CODE: Assemble Final Data').first();

return {
  json: {
    ...base.json,
    _approval: {
      reply:         isTimedOut ? 'timeout (auto-proceed)' : reply,
      isRejected:    isStop,
      isApproved:    isApprove,
      timedOut:      isTimedOut
    }
  },
  binary: base.binary
};

// Capture result of fb_page_post upload
const httpResult = $input.item.json;
const isError    = httpResult != null && (
  httpResult.error != null ||
  (typeof httpResult.message === 'string' && httpResult.message.toLowerCase().includes('error')) ||
  (httpResult.statusCode != null && httpResult.statusCode >= 400)
);

// Get accumulated status from previous capture (or init)
const prevJson = $("\ud83e\udde9 CODE: Assemble Final Data").first().json;
const status   = { ...(prevJson._status || {}) };
status["fb_page_post"] = {
  ok:    !isError,
  error: isError ? (
    httpResult?.error?.message ||
    httpResult?.message ||
    JSON.stringify(httpResult).substring(0, 200)
  ) : null
};

// Re-attach binary and pass full data forward
const base = $("\ud83e\udde9 CODE: Assemble Final Data").first();
return {
  json:   { ...base.json, _status: status },
  binary: base.binary
};

