const s = $input.item.json._status || {};

// Platform display order
const platforms = [
  { key: 'fb_page_post',  label: '[1/10] Facebook Page Post',  emoji: '📘' },
  { key: 'fb_reels',      label: '[2/10] Facebook Reels',       emoji: '📘' },
  { key: 'fb_story',      label: '[3/10] Facebook Story',       emoji: '📘' },
  { key: 'ig_post',       label: '[4/10] Instagram Post',       emoji: '📸' },
  { key: 'ig_reels',      label: '[5/10] Instagram Reels',      emoji: '📸' },
  { key: 'ig_story',      label: '[6/10] Instagram Story',      emoji: '📸' },
  { key: 'yt_video',      label: '[7/10] YouTube Video',        emoji: '▶️' },
  { key: 'yt_shorts',     label: '[8/10] YouTube Shorts',       emoji: '▶️' },
  { key: 'tt_video',      label: '[9/10] TikTok Video',         emoji: '🎵' },
  { key: 'tt_story',      label: '[10/10] TikTok Story',        emoji: '🎵' },
];

let successCount = 0;
let failCount = 0;
const rows = [];

for (const p of platforms) {
  const r = s[p.key];
  if (!r) {
    rows.push(`⚠️ ${p.label}: Not reached`);
    continue;
  }
  if (r.ok) {
    successCount++;
    rows.push(`✅ ${p.label}`);
  } else {
    failCount++;
    rows.push(`❌ ${p.label}`);
    rows.push(`   └ Error: ${(r.error || 'unknown').substring(0, 150)}`);
  }
}

const base = $input.item.json;
const overall = failCount === 0 ? '✅ All uploaded successfully' :
                successCount === 0 ? '❌ All uploads failed' :
                `⚠️ ${successCount}/10 succeeded, ${failCount} failed`;

const msg = [
  '🎬 *Upload Report*',
  '━━━━━━━━━━━━━━━━━━━━━━━━━',
  '📁 ' + base.fileName,
  '━━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  ...rows,
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━',
  '📊 ' + overall,
  '📁 Moved to: Completed Folder',
  '⏰ ' + new Date().toLocaleString('en-US', { timeZone: 'Asia/Kathmandu' }) + ' (NPT)',
].join('\n');

// Build sheets row
const sheetRow = [
  new Date().toISOString(),
  base.fileName,
  base.fileId,
  ...platforms.map(p => {
    const r = s[p.key];
    if (!r) return 'Not reached';
    return r.ok ? 'OK' : ('ERROR: ' + (r.error || '').substring(0, 100));
  }),
  overall
];

return {
  json: {
    ...base,
    _report:    msg,
    _sheetRow:  sheetRow,
    _successCount: successCount,
    _failCount:    failCount,
    _overall:   overall
  }
};
